Method.Implementation:
	set stat = $$$OK
	set sequenceID = 0
	if (sessionID = 0)
	{
		set sessionID = $$$JobSessionId
	}
	if (procDtTm = "")
	{
		set procDtTm = $ZDATETIME($HOROLOG,3, 1)
	}
	Do inpStream.Rewind()
	$$$TRACE("In StoreErpData: " _ flNm _", " _ inpStream.Size)
	set x12Doc = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(inpStream, .sc)
	if ( ($$$ISOK(sc)) && ($IsObject(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
	{

			 // WRITE !, x12Doc.DocType _", " _ sc _", " _ x12Doc.OutputToString()
			 set x12Doc.DocType = "ERP_4010:Interchange:Group"

			 set isaInterchangeSenderID = x12Doc.GetValueAt("ISA:InterchangeSenderID")
			 set isaInterchangeReceiverID = x12Doc.GetValueAt("ISA:InterchangeReceiverID")
			 set isaControlNumber = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
			 set isaDT = x12Doc.GetValueAt("ISA:InterchangeDate")
			 set isaTM = x12Doc.GetValueAt("ISA:InterchangeTime")

			 Set k1="",tSC=1,k2=""
			 set nxt = x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans)
			 Set k1=x12Doc.NextChild(k1,nxt)
			 set parentId = 0
			while ($IsObject(k1))
			{

				If ""=k1.DocType {
					Set tDocType = k1.resolveChildDocType()

					Set tSC =k1.PokeDocType(tDocType)
				}

				 set applicationSendersCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationSendersCode") , "<>W")
				 set applicationReceiversCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationReceiversCode"), "<>W")
				 set grpCtrlNum = $ZSTRIP(k1.GetValueAt("GS:GroupControlNumber"), "<>W")
				 set numTransactions = $ZSTRIP(k1.GetValueAt("GE:1"), "<>W")
				 set grpDocType = k1.DocType
				 $$$TRACE(  "GS Sender: " _ applicationSendersCode _ " -> " _ applicationReceiversCode_ " , GS Ctrl # " _ grpCtrlNum)

				Set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
			}

		  	Set k1="",tSC=1,k2=""


		   	Set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		   	set stCnt = 0, processSt = 1, accNum = 0, eddOverride = ""
		    while ( ($IsObject(k1)) && (processSt = 1))
		    {

				Set x12Doc.FunctionalGroups(k1)=k1

		 		Set k2=x12Doc.FunctionalGroups(k1).NextChild(k2,x12Doc.FunctionalGroups(k1).GetSegmentIndex("TransactionSetDocsRef",.tSCTrans))
		 		while ( ($IsObject(k2)) && (processSt = 1))
		 		{
			 		Do $INCREMENT( stCnt )
					$$$TRACE("--ST: " _ stCnt _"= " _ k2.SegCountGet()) 
					set sequenceID = stCnt
					$$$TRACE("--SequenceID: " _ sequenceID) 

					Set x12Doc.FunctionalGroups(k1).TransactionSets(k2)=k2
					If ""=k2.DocType {
						Set tDocType = k2.resolveChildDocType()
						Set tSC =k2.PokeDocType(tDocType)
					}

					set documentType = "", invoiceNumber = "", purchaseOrder = "", productTransfer = ""
					set stCtrlNum = "", numSegs = 0
					FOR seg=1:1:k2.SegCountGet()
					{

						Do $INCREMENT(numSegs)
						set segRec = k2.GetValueAt(seg)
						set recType = k2.GetValueAt(seg_":0")
						if (recType = "ST")
						{
							set documentType = k2.GetValueAt(seg_":1")
							set stCtrlNum = k2.GetValueAt(seg_":2")
						}
						if (recType = "SE")
						{
							set seCtrlNum = $ZSTRIP(k2.GetValueAt(seg_":2"), "<>W")
							set seNumSegs = $ZSTRIP(k2.GetValueAt(seg_":1"), "<>W")
							$$$TRACE("ST-SE segment CTRL NUM / counts: " _ numSegs _ ", " _ seNumSegs _", CTRl # " _ stCtrlNum _ ", " _ seCtrlNum)
							if ( (numSegs '= seNumSegs) || (stCtrlNum '= seCtrlNum))
							{
								$$$LOGERROR( "ST segment CTRL NUM / counts did not match: " _ numSegs _ " '= " _ seNumSegs _", CTRl # " _ stCtrlNum _ " '= " _ seCtrlNum)
								QUIT 
							}
						}
						if (documentType = "810")
						{
							if (recType = "BIG")
							{
								set invoiceNumber = k2.GetValueAt(seg_":2") 
								set purchaseOrder = k2.GetValueAt(seg_":4")
							}
							if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
							elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
							{
								set eddOverride = k2.GetValueAt(seg_":4")
							}
							elseif ( (accNum = 0) && (recType = "N1") && (k2.GetValueAt(seg_":1") = "BS"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
							elseif ( (accNum = 0) && (recType = "N1") && (k2.GetValueAt(seg_":1") = "OB"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
						}
						elseif (documentType = "846")
						{
							if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
							elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
							{
								set eddOverride = k2.GetValueAt(seg_":4")
							}
						}
						elseif (documentType = "850")
						{
							if (recType = "BEG")
							{
								set purchaseOrder = k2.GetValueAt(seg_":3")
							}
							if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
							elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
							{
								set eddOverride = k2.GetValueAt(seg_":4")
							}
						}
						elseif (documentType = "852")
						{
							if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "RL"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
							elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
							{
								set eddOverride = k2.GetValueAt(seg_":4")
							}
						}
						elseif (documentType = "855")
						{
							if (recType = "BAK")
							{
								set purchaseOrder = k2.GetValueAt(seg_":3")
								// WRITE !, "-- PurchaseOrder: " _ stCtrlNum _". " _ purchaseOrder
							}
							if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
							elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
							{
								set eddOverride = k2.GetValueAt(seg_":4")
							}
						}
						elseif (documentType = "856")
						{
							if (recType = "PRF")
							{
								set purchaseOrder = k2.GetValueAt(seg_":1")
							}
							if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
							elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
							{
								set eddOverride = k2.GetValueAt(seg_":4")
							}
						}
						elseif (documentType = "861")
						{
							if (recType = "PRF")
							{
								set purchaseOrder = k2.GetValueAt(seg_":1")
							}
							if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
							{
								set accNum = k2.GetValueAt(seg_":4")
							}
						}
						elseif (documentType = "867")
						{
							if (recType = "BPT")
							{
								set productTransfer = k2.GetValueAt(seg_":2")
							}
						}
						elseif ((documentType = "997") || (documentType = "832"))
						{
							$$$TRACE("No additional fields stored for " _ documentType)
							set processSt = 0 // Don't store ST-SE as a new record
							QUIT
						}
						else
						{
							set stat = $$$ERROR($$$DocumentNameInvalid, documentType _" not processed")
							set processSt = 0 // Don't store ST-SE as a new record
							QUIT
						}
					}

					if (stCnt = 1)
					{
						// Store Full X12
						$$$TRACE( "Store Full X12 string")
						if (numTransactions > 1)
						{
							set numSegs = ""
						}
						set purchaseOrder = $zconvert(purchaseOrder, "U")

					    if (inpStream.Size < 3641144)
					    {
						    set x12DocStr = x12Doc.OutputToString()
						    &SQL(INSERT INTO IHC_ERP.X12Data
						    (ProcessDtTm, ApplicationReceiversCode, ApplicationSendersCode, FileName, GroupControlNumber, 
						    InterchangeControlNumber, InterchangeDate, InterchangeTime, InterchangeReceiverID, InterchangeSenderID, 
						     TransactionType,InvoiceNumber, ProductTransfer, PurchaseOrder, 
						     x12Data, NumTransactions, TransactionControlNumber, NumSegments, ParentId, AccountNumber, EddOverride, SessionID, SequenceID)
						    values 
						    (:procDtTm, :applicationReceiversCode, :applicationSendersCode, :flNm, :grpCtrlNum, 
						    :isaControlNumber,:isaDT, :isaTM, :isaInterchangeReceiverID,:isaInterchangeSenderID,
						    :documentType, :invoiceNumber, :productTransfer, :purchaseOrder, :x12DocStr,
						    :numTransactions, :stCtrlNum, :numSegs, 0, :accNum, :eddOverride, :sessionID, 0 ))


						    IF SQLCODE<0 {
							  $$$LOGERROR( "SQLCODE error " _ SQLCODE)  
							  if (SQLCODE = -119)
							  {
								  $$$TRACE( " - Duplicate Row")
							  }
							  else
							  {
								$$$LOGERROR(  procDtTm_", "_applicationReceiversCode_", "_applicationSendersCode_", "_flNm_", "_grpCtrlNum)
						    	$$$LOGERROR(  isaControlNumber_", "_isaDT_", "_isaTM_", "_isaInterchangeReceiverID_", "_isaInterchangeSenderID)
						    	$$$LOGERROR(  documentType_", "_invoiceNumber_", "_productTransfer_", "_purchaseOrder_", "_x12DocStr)
						    	set stat = $$$ERROR($$$SQLError,"INSERT INTO IHC_ERP.X12Data: SQLCODE error " _ SQLCODE) 
							  	QUIT
							  }
						    }
						    else
						    {
							    $$$TRACE( "INSERT INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID)
							    set parentId = %ROWID
							    // WRITE !, "     -- INSERT INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID
						    }

					    }
					    else
					    {
						    set purchaseOrder = $zconvert(purchaseOrder, "U")
							set myquery = "INSERT INTO IHC_ERP.X12Data"
						    _"(ProcessDtTm, ApplicationReceiversCode, ApplicationSendersCode, FileName, GroupControlNumber, "
						    _"InterchangeControlNumber, InterchangeDate, InterchangeTime, InterchangeReceiverID, InterchangeSenderID, "
						     _"TransactionType,InvoiceNumber, ProductTransfer, PurchaseOrder,"
						     _" NumTransactions, TransactionControlNumber, NumSegments, ParentId, AccountNumber, EddOverride, SessionID, SequenceID )"
						    _"values "
						    _"(:procDtTm, :applicationReceiversCode, :applicationSendersCode, :flNm, :grpCtrlNum, "
						    _":isaControlNumber,:isaDT, :isaTM, :isaInterchangeReceiverID,:isaInterchangeSenderID,"
						    _":documentType, :invoiceNumber, :productTransfer, :purchaseOrder,"
						    _":numTransactions, :stCtrlNum, :numSegs, 0, :accNum, :eddOverride, :sessionID, 0 )"
						    SET tStatement = ##class(%SQL.Statement).%New()
							SET tStatus = tStatement.%Prepare(myquery)
							SET rset = tStatement.%Execute()

							if (rset.%SQLCODE = 0)
							{		
								set rowId = rset.%ROWID
								set parentId = rset.%ROWID

									 set obj = ##class(IHC.ERP.X12Data).%OpenId(rowId)
									 if ($ISOBJECT(obj))
									 {

										 set obj.x12DataStream = inpStream

										 set obj.x12Data = ""
										 set stat = obj.%Save()
										 $$$TRACE( "Save stream with IHC_ERP.X12Data: " _ obj.%Id())
										 WRITE !, "     -- Save stream with IHC_ERP.X12Data: " _ obj.%Id()
									 }
									 else
									 {
										 set stat = $$$ERROR($$$SQLError, "Row ID not found: " _ rowId)
									 }


					    	}
					    	else
					    	{
						    	set stat = $$$ERROR($$$SQLError, myquery _ ": Execute SQLCODE error " _ rset.%SQLCODE)
						    	QUIT
					    	}
					    }

					} // ISA-IEA

					if ((processSt = 1) &&(numTransactions >= 1))
					{
						// Store ST-SE
						$$$TRACE( "Store ST-SE, CTRL # " _ stCtrlNum)
						set purchaseOrder = $zconvert(purchaseOrder, "U")
						set stX12 = k2.OutputToString()
					    &SQL(INSERT INTO IHC_ERP.X12Data
					    (ProcessDtTm, ApplicationReceiversCode, ApplicationSendersCode, FileName, GroupControlNumber, 
					    InterchangeControlNumber, InterchangeDate, InterchangeTime, InterchangeReceiverID, InterchangeSenderID, 
					     TransactionType,InvoiceNumber, ProductTransfer, PurchaseOrder, 
					     x12Data, NumTransactions, TransactionControlNumber, NumSegments, ParentId, AccountNumber, EddOverride, SessionID, SequenceID)
					    values 
					    (:procDtTm, :applicationReceiversCode, :applicationSendersCode, :flNm, :grpCtrlNum, 
					    :isaControlNumber,:isaDT, :isaTM, :isaInterchangeReceiverID,:isaInterchangeSenderID,
					    :documentType, :invoiceNumber, :productTransfer, :purchaseOrder, :stX12,
					    :numTransactions, :stCtrlNum, :numSegs, :parentId, :accNum, :eddOverride, :sessionID, :sequenceID ))
					    if (SQLCODE<0)
				    	{
					    	set stat = $$$ERROR($$$SQLError, "ST x12 store SQLCODE error " _ rset.%SQLCODE)
					    	QUIT
				    	}
				    	else
						{
							$$$TRACE( "INSERT ST-SE INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID _", Parent: " _ parentId)
							// WRITE !, "       ---  INSERT ST-SE INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID _", Parent: " _ parentId

						}
					}

		    		Set k2=x12Doc.FunctionalGroups(k1).NextChild(k2,x12Doc.FunctionalGroups(k1).GetSegmentIndex("TransactionSetDocsRef",.tSCTrans))			

		 		}
		  		Set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		  } 
	 } // X12
	 else
	 {
		  #dim tDocument As %XML.XPATH.Document;
		  Set tSC=##class(%XML.XPATH.Document).CreateFromStream(inpStream,.tDocument)

		  if ( ($$$ISOK(tSC)) && ($IsObject( tDocument)))
		  {
			  $$$TRACE( "**** XML file " _ flNm)
			  set sender = ""
			  set gtin = "", tran = ""
			  set receiver = ""
			  set catPathStr(1) = "/catalogue_item_notification:catalogueItemNotificationMessage/sh:StandardBusinessDocumentHeader/sh:Sender/sh:Identifier"					  
  			  set catPathStr(2) = "/catalogue_item_notification:catalogueItemNotificationMessage/sh:StandardBusinessDocumentHeader/sh:Receiver/sh:Identifier"					  		
			  set catPathStr(3) = "//catalogue_item_notification:catalogueItemNotificationMessage/transaction/documentCommand/catalogue_item_notification:catalogueItemNotification/catalogueItem/tradeItem/gtin"

			  set ordPathStr(1) = "//cXML/Header/From/Credential/Identity"
			  set ordPathStr(2) = "//cXML/Header/To/Credential/Identity"
			  set expr = "text()"


			        Set tSC=tDocument.EvaluateExpression(catPathStr(1), expr, .xPathDoc)

			        If $$$ISOK(tSC) { 

			        	// WRITE !, "catalogue_item_notification - Xpath count: " _ xPathDoc.Count()
			        	set tran = "CatalogueItemNotification"
			        	Set tSC=tDocument.EvaluateExpression(catPathStr(2), expr, .xPathDoc2)
			        	if (xPathDoc2.Count() > 0)
					 	{
						 	set receiver = xPathDoc2.GetAt(1).Value

					 	}
					 	Set tSC=tDocument.EvaluateExpression(catPathStr(3), expr, .xPathDoc3)
			        	if (xPathDoc3.Count() > 0)
					 	{
						 	set gtin = xPathDoc3.GetAt(1).Value

					 	}
			        }
			        else
			        {
				        Do $System.Status.DisplayError(tSC) 
				        Set tSC=tDocument.EvaluateExpression(ordPathStr(1), expr, .xPathDoc)
				        If $$$ISERR(tSC) { Do $System.Status.DisplayError(tSC) Quit}

				        // WRITE !, "orderrequest - Xpath count: " _ xPathDoc.Count()
				        set tran = "OrderRequest"
				        Set tSC=tDocument.EvaluateExpression(ordPathStr(2), expr, .xPathDoc2)
				        if (xPathDoc2.Count() > 0)
					 	{
						 	set receiver = xPathDoc2.GetAt(1).Value

					 	}
			        }
			        if (xPathDoc.Count() > 0)
					 {
						 set sender = xPathDoc.GetAt(1).Value

					 }


					  set xmlStr = ""

					  $$$TRACE( "Stream length: " _ inpStream.Size)

					 if (inpStream.Size < 3641144)
					 {

						 set len = 32000
						 Do inpStream.Rewind()
						 while (len = 32000)
						 {
							 set len = 32000
						 	 set xmlStr = xmlStr _ inpStream.Read(.len, .st)

						 }


						 $$$TRACE( "Stream Read to String" _ st _", length: " _ $L(xmlStr) _", " _ len)

						  &SQL(INSERT INTO IHC_ERP.XMLData
							    (ProcessDtTm,  FileName, xmlData, SenderID, ReceiverID, Gtin, TransactionType, SessionID, SequenceID)
							    values 
							    (:procDtTm, :flNm, :xmlStr, :sender, :receiver,:gtin, :tran, :sessionID, :sequenceID  ))
						  IF SQLCODE<0 {
							  $$$LOGERROR( "SQLCODE error " _ SQLCODE _ " " _ %msg)  
						  		if (SQLCODE = -119)
							  {
								  $$$TRACE( " - Duplicate Row")
							  }
							  else
							  {
								set stat = $$$ERROR($$$SQLError,  procDtTm_", "_receiver_", "_sender_", "_flNm)
						   	  	QUIT
							  }
						  }
						  else
						  {
						     $$$TRACE("INSERT INTO IHC_ERP.XMLData. SQLCODE: " _ SQLCODE _ ", Count: " _ %ROWCOUNT _ "; ROWID: " _ %ROWID)

						  }
					 }
					 else // XML stream
					 {
						 set xmlStr = ""
						 &SQL(INSERT INTO IHC_ERP.XMLData
							    (ProcessDtTm,  FileName, xmlData, SenderID, ReceiverID, Gtin, TransactionType, SessionID, SequenceID)
							    values 
							    (:procDtTm, :flNm, :xmlStr, :sender, :receiver,:gtin, :tran, :sessionID, :sequenceID  ))
						  IF SQLCODE<0 {
							  $$$LOGERROR( "SQLCODE error " _ SQLCODE _ " " _ %msg)  
						  		if (SQLCODE = -119)
							  {
								  $$$TRACE( " - Duplicate Row")
							  }
							  else
							  {
								set stat = $$$ERROR($$$SQLError,  procDtTm_", "_receiver_", "_sender_", "_flNm)
						   	  	QUIT
							  }
						  }
						  else
						  {
							 set rowId = %ROWID
						     $$$TRACE( "INSERT INTO IHC_ERP.XMLData Count: " _", " _ %ROWCOUNT _ "; ROWID: " _ rowId)
							 set obj = ##class(IHC.ERP.XMLData).%OpenId(rowId)
							 if ($ISOBJECT(obj))
							 {

								 set obj.xmlDataStream = inpStream

								 set stat = obj.%Save()
								 $$$TRACE( "Save stream with IHC_ERP.XMLData: " _ obj.%Id())
							 }   
						  }
					 }



		 } //XML

		 else
		 {
			 $$$TRACE( "  -- CFF file " _ flNm)
			 if (flNm [ "payp") || (flNm [ "PAYP")
			 {
			 	set tran = "PAYP"
			 }
			 elseif (flNm [ "nacha") || (flNm [ "NACHA")
			 {
			 	set tran = "NACHA"
			 }
			 elseif (flNm [ "psbd") || (flNm [ "PSBD")
			 {
			 	set tran = "PSBD1"
			 }
			 elseif (flNm [ "bai2") || (flNm [ "BAI2")
			 {
			 	set tran = "BAI2"
			 }
			 else
			 {
				 QUIT
			 }


			  $$$TRACE( "Stream length: " _ inpStream.Size)
			  set dataStr = ""

			 set len = 32000
			 Do inpStream.Rewind()
			 while (len = 32000)
			 {
				 set len = 32000
			 	 set dataStr = dataStr _ inpStream.Read(.len, .st)

			 }

			 &SQL(INSERT INTO IHC_ERP.TextData
				    (ProcessDtTm,  FileName, textData, SenderID, ReceiverID, TransactionType, SessionID, SequenceID)
				    values 
				    (:procDtTm, :flNm, :dataStr, '-', '-', :tran, :sessionID, :sequenceID  ))
				    $$$TRACE( "Insert: " _ tran _": " _ SQLCODE)
				    IF SQLCODE<0 {
				    	set stat = $$$ERROR($$$SQLError, "INSERT INTO IHC_ERP.TextData failed: " _ SQLCODE)
				    }
		 } // CFF

	 }
	 return stat

	set stat = $$$OK
	set sequenceID = 0
	if (sessionID = 0)
	{
		set sessionID = $$$JobSessionId
	}
	if (procDtTm = "")
	{
		set procDtTm = $ZDATETIME($HOROLOG,3, 1)
	}
	Do inpStream.Rewind()
	$$$TRACE("In StoreErpX12Data: " _ flNm _", " _ inpStream.Size)
	set x12Doc = ##class(EnsLib.EDI.X12.Document).ImportFromLibraryStream(inpStream, .sc)
	if ( ($$$ISOK(sc)) && ($IsObject(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
	{
		// WRITE !, x12Doc.DocType _", " _ sc _", " _ x12Doc.OutputToString()
		set x12Doc.DocType = "ERP_4010:Interchange:Group"
		set isaInterchangeSenderID = x12Doc.GetValueAt("ISA:InterchangeSenderID")
		set isaInterchangeReceiverID = x12Doc.GetValueAt("ISA:InterchangeReceiverID")
		set isaControlNumber = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
		set isaDT = x12Doc.GetValueAt("ISA:InterchangeDate")
		set isaTM = x12Doc.GetValueAt("ISA:InterchangeTime")
		set k1="",tSC=1,k2=""
		set nxt = x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans)
		set k1=x12Doc.NextChild(k1,nxt)
		set parentId = 0
		while ($IsObject(k1))
		{
			If ""=k1.DocType
			{
				set tDocType = k1.resolveChildDocType()
				set tSC =k1.PokeDocType(tDocType)
			}
			set applicationSendersCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationSendersCode") , "<>W")
			set applicationReceiversCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationReceiversCode"), "<>W")
			set grpCtrlNum = $ZSTRIP(k1.GetValueAt("GS:GroupControlNumber"), "<>W")
			set numTransactions = $ZSTRIP(k1.GetValueAt("GE:1"), "<>W")
			set grpDocType = k1.DocType
			$$$TRACE(  "GS Sender: " _ applicationSendersCode _ " -> " _ applicationReceiversCode_ " , GS Ctrl # " _ grpCtrlNum)
			set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		}
		set k1="",tSC=1,k2=""
		set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		set stCnt = 0, processSt = 1, accNum = 0, eddOverride = ""
		while ( ($IsObject(k1)) && (processSt = 1))
		{
			set x12Doc.FunctionalGroups(k1)=k1
			set k2=x12Doc.FunctionalGroups(k1).NextChild(k2,x12Doc.FunctionalGroups(k1).GetSegmentIndex("TransactionSetDocsRef",.tSCTrans))
			while ( ($IsObject(k2)) && (processSt = 1))
			{
				Do $INCREMENT( stCnt )
				$$$TRACE("--ST: " _ stCnt _"= " _ k2.SegCountGet()) 
				set sequenceID = stCnt
				set x12Doc.FunctionalGroups(k1).TransactionSets(k2)=k2
				If ""=k2.DocType 
				{
					set tDocType = k2.resolveChildDocType()
					set tSC =k2.PokeDocType(tDocType)
				}
				set documentType = "", invoiceNumber = "", purchaseOrder = "", productTransfer = ""
				set stCtrlNum = "", numSegs = 0
				FOR seg=1:1:k2.SegCountGet()
				{
					Do $INCREMENT(numSegs)
					set segRec = k2.GetValueAt(seg)
					set recType = k2.GetValueAt(seg_":0")
					if (recType = "ST")
					{
						set documentType = k2.GetValueAt(seg_":1")
						set stCtrlNum = k2.GetValueAt(seg_":2")
					}
					if (recType = "SE")
					{
						set seCtrlNum = $ZSTRIP(k2.GetValueAt(seg_":2"), "<>W")
						set seNumSegs = $ZSTRIP(k2.GetValueAt(seg_":1"), "<>W")
						$$$TRACE("ST-SE segment CTRL NUM / counts: " _ numSegs _ ", " _ seNumSegs _", CTRl # " _ stCtrlNum _ ", " _ seCtrlNum)
						if ((numSegs '= seNumSegs) || (stCtrlNum '= seCtrlNum))
						{
							$$$LOGERROR( "ST segment CTRL NUM / counts did not match: " _ numSegs _ " '= " _ seNumSegs _", CTRl # " _ stCtrlNum _ " '= " _ seCtrlNum)
							QUIT 
						}
					}
					if (documentType = "810")
					{
						if (recType = "BIG")
						{
							set invoiceNumber = k2.GetValueAt(seg_":2") 
							set purchaseOrder = k2.GetValueAt(seg_":4")
						}
						if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
						elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
						{
							set eddOverride = k2.GetValueAt(seg_":4")
						}
						elseif ( (accNum = 0) && (recType = "N1") && (k2.GetValueAt(seg_":1") = "BS"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
						elseif ( (accNum = 0) && (recType = "N1") && (k2.GetValueAt(seg_":1") = "OB"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
					}
					elseif (documentType = "846")
					{
						if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
						elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
						{
							set eddOverride = k2.GetValueAt(seg_":4")
						}
					}
					elseif (documentType = "850")
					{
						if (recType = "BEG")
						{
							set purchaseOrder = k2.GetValueAt(seg_":3")
						}
						if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
						elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
						{
							set eddOverride = k2.GetValueAt(seg_":4")
						}
					}
					elseif (documentType = "852")
					{
						if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "RL"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
						elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
						{
							set eddOverride = k2.GetValueAt(seg_":4")
						}
					}
					elseif (documentType = "855")
					{
						if (recType = "BAK")
						{
							set purchaseOrder = k2.GetValueAt(seg_":3")
							// WRITE !, "-- PurchaseOrder: " _ stCtrlNum _". " _ purchaseOrder
						}
						if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
						elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
						{
							set eddOverride = k2.GetValueAt(seg_":4")
						}
					}
					elseif (documentType = "856")
					{
						if (recType = "PRF")
						{
							set purchaseOrder = k2.GetValueAt(seg_":1")
						}
						if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
						elseif ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "SE"))
						{
							set eddOverride = k2.GetValueAt(seg_":4")
						}
					}
					elseif (documentType = "861")
					{
						if (recType = "PRF")
						{
							set purchaseOrder = k2.GetValueAt(seg_":1")
						}
						if ( (recType = "N1") && (k2.GetValueAt(seg_":1") = "ST"))
						{
							set accNum = k2.GetValueAt(seg_":4")
						}
					}
					elseif (documentType = "867")
					{
						if (recType = "BPT")
						{
						set productTransfer = k2.GetValueAt(seg_":2")
						}
					}
					elseif ((documentType = "997") || (documentType = "832"))
					{
						$$$TRACE("No additional fields stored for " _ documentType)
						set processSt = 0 // Don't store ST-SE as a new record
						QUIT
					}
					else
					{
						set stat = $$$ERROR($$$DocumentNameInvalid, documentType _" not processed")
						set processSt = 0 // Don't store ST-SE as a new record
						QUIT
					}
				} //endfor

				// Start ISA-IEA
				if (stCnt = 1)
				{
					// Store Full X12
					$$$TRACE( "Store Full X12 string")
					if (numTransactions > 1)
					{
					set numSegs = ""
					}
					set purchaseOrder = $zconvert(purchaseOrder, "U")

					if (inpStream.Size < 3641144)
					{
						set x12DocStr = x12Doc.OutputToString()
						&SQL(INSERT INTO IHC_ERP.X12Data
							(ProcessDtTm, ApplicationReceiversCode, ApplicationSendersCode, FileName, GroupControlNumber, 
							InterchangeControlNumber, InterchangeDate, InterchangeTime, InterchangeReceiverID, InterchangeSenderID, 
							TransactionType,InvoiceNumber, ProductTransfer, PurchaseOrder, 
							x12Data, NumTransactions, TransactionControlNumber, NumSegments, ParentId, AccountNumber, EddOverride, SessionID, SequenceID)
							values 
							(:procDtTm, :applicationReceiversCode, :applicationSendersCode, :flNm, :grpCtrlNum, 
							:isaControlNumber,:isaDT, :isaTM, :isaInterchangeReceiverID,:isaInterchangeSenderID,
							:documentType, :invoiceNumber, :productTransfer, :purchaseOrder, :x12DocStr,
							:numTransactions, :stCtrlNum, :numSegs, 0, :accNum, :eddOverride, :sessionID, 0 ))

						IF SQLCODE<0
						{
							$$$LOGERROR( "SQLCODE error " _ SQLCODE)  
							if (SQLCODE = -119)
							{
								$$$TRACE( " - Duplicate Row")
							}
							else
							{
								$$$LOGERROR(  procDtTm_", "_applicationReceiversCode_", "_applicationSendersCode_", "_flNm_", "_grpCtrlNum)
								$$$LOGERROR(  isaControlNumber_", "_isaDT_", "_isaTM_", "_isaInterchangeReceiverID_", "_isaInterchangeSenderID)
								$$$LOGERROR(  documentType_", "_invoiceNumber_", "_productTransfer_", "_purchaseOrder_", "_x12DocStr)
								set stat = $$$ERROR($$$SQLError,"INSERT INTO IHC_ERP.X12Data: SQLCODE error " _ SQLCODE) 
								QUIT
							}
						}
						else
						{
							$$$TRACE( "INSERT INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID)
							set parentId = %ROWID
							// WRITE !, "     -- INSERT INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID
						}

					}
					else
					{
						set purchaseOrder = $zconvert(purchaseOrder, "U")
						set myquery = "INSERT INTO IHC_ERP.X12Data"
							_"(ProcessDtTm, ApplicationReceiversCode, ApplicationSendersCode, FileName, GroupControlNumber, "
							_"InterchangeControlNumber, InterchangeDate, InterchangeTime, InterchangeReceiverID, InterchangeSenderID, "
							_"TransactionType,InvoiceNumber, ProductTransfer, PurchaseOrder,"
							_" NumTransactions, TransactionControlNumber, NumSegments, ParentId, AccountNumber, EddOverride, SessionID, SequenceID )"
							_"values "
							_"(:procDtTm, :applicationReceiversCode, :applicationSendersCode, :flNm, :grpCtrlNum, "
							_":isaControlNumber,:isaDT, :isaTM, :isaInterchangeReceiverID,:isaInterchangeSenderID,"
							_":documentType, :invoiceNumber, :productTransfer, :purchaseOrder,"
							_":numTransactions, :stCtrlNum, :numSegs, 0, :accNum, :eddOverride, :sessionID, 0 )"
						set tStatement = ##class(%SQL.Statement).%New()
						set tStatus = tStatement.%Prepare(myquery)
						set rset = tStatement.%Execute()

						if (rset.%SQLCODE = 0)
						{		
							set rowId = rset.%ROWID
							set parentId = rset.%ROWID
							set obj = ##class(IHC.ERP.X12Data).%OpenId(rowId)
							if ($ISOBJECT(obj))
							{
								set obj.x12DataStream = inpStream
								set obj.x12Data = ""
								set stat = obj.%Save()
								$$$TRACE( "Save stream with IHC_ERP.X12Data: " _ obj.%Id())
								WRITE !, "     -- Save stream with IHC_ERP.X12Data: " _ obj.%Id()
							}
							else
							{
								set stat = $$$ERROR($$$SQLError, "Row ID not found: " _ rowId)
							}
						}
						else
						{
							set stat = $$$ERROR($$$SQLError, myquery _ ": Execute SQLCODE error " _ rset.%SQLCODE)
							QUIT
						}
					}

				} // End ISA-IEA

				// Start ST-SE
				if ((processSt = 1) &&(numTransactions >= 1))
				{
					// Store ST-SE
					$$$TRACE( "Store ST-SE, CTRL # " _ stCtrlNum)
					set purchaseOrder = $zconvert(purchaseOrder, "U")
					set stX12 = k2.OutputToString()
					&SQL(INSERT INTO IHC_ERP.X12Data
						(ProcessDtTm, ApplicationReceiversCode, ApplicationSendersCode, FileName, GroupControlNumber, 
						InterchangeControlNumber, InterchangeDate, InterchangeTime, InterchangeReceiverID, InterchangeSenderID, 
						TransactionType,InvoiceNumber, ProductTransfer, PurchaseOrder, 
						x12Data, NumTransactions, TransactionControlNumber, NumSegments, ParentId, AccountNumber, EddOverride, SessionID, SequenceID)
						values 
						(:procDtTm, :applicationReceiversCode, :applicationSendersCode, :flNm, :grpCtrlNum, 
						:isaControlNumber,:isaDT, :isaTM, :isaInterchangeReceiverID,:isaInterchangeSenderID,
						:documentType, :invoiceNumber, :productTransfer, :purchaseOrder, :stX12,
						:numTransactions, :stCtrlNum, :numSegs, :parentId, :accNum, :eddOverride, :sessionID, :sequenceID ))
					if (SQLCODE<0)
					{
						set stat = $$$ERROR($$$SQLError, "ST x12 store SQLCODE error " _ rset.%SQLCODE)
						QUIT
					}
					else
					{
						$$$TRACE( "INSERT ST-SE INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID _", Parent: " _ parentId)
						// WRITE !, "       ---  INSERT ST-SE INTO IHC_ERP.X12Data successful. Count: " _ %ROWCOUNT _ ", ROWID: " _ %ROWID _", Parent: " _ parentId
					}
				} // End ST-SE
				set k2=x12Doc.FunctionalGroups(k1).NextChild(k2,x12Doc.FunctionalGroups(k1).GetSegmentIndex(" TransactionSetDocsRef",.tSCTrans)) 
			} //while2
			set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		} //while1
}

	// x12
	return stat

	set stat = $$$OK
	if (sessionID = 0)
	{
		set sessionID = $$$JobSessionId
	}
	if (procDtTm = "")
	{
		set procDtTm = $ZDATETIME($HOROLOG,3, 1)
	}
	Do inpStream.Rewind()
	$$$TRACE("In StoreErpXmlData: " _ flNm _", " _ inpStream.Size)

    Set tDocument=##class(EnsLib.EDI.XML.Document).ImportFromLibraryStream(inpStream, .tSC)
	if ( ($$$ISOK(tSC)) && ($IsObject( tDocument)))
	{
		$$$TRACE( "**** XML file " _ flNm)
		set tran = tDocument.Name
		set sender = "IRIS-Workday"
		set gtin = ""
		set receiver = ""
		set purchaseOrder = ""

	    If ((tran = "Invoice") || (tran = "PurchaseOrder") || (tran = "PurchaseOrderAcknowledgement") || (tran = "AdvanceShipNotice") || (tran = "ReceivingAdvice"))
	    {
		    set xmlPath = "/" _ tran _ "/HeaderDetail/EdiDocumentInfo/GroupReceiverId"
		    set receiver = tDocument.GetValueAt(xmlPath)
		    set xmlPath = "/" _ tran _ "/HeaderDetail/PurchaseOrder"
		    set purchaseOrder = tDocument.GetValueAt(xmlPath)
	    }
	   	elseif (tran = "WorkdayItemMaster")
	    {
		    set receiver = "Epic"
	    }
	   	elseif (tran = "TissueTracking")
	    {
		    set xmlPath = "/" _ tran _ "/Purchase_Order_Number"
		    set purchaseOrder = tDocument.GetValueAt(xmlPath)
		    set receiver = "TrackCore"
	    }	
	   	elseif (tran = "InventoryRelief")
	    {
		    set receiver = "Workday"
	    }	

		set xmlStr = ""

		$$$TRACE( "Stream length: " _ inpStream.Size)

		if (inpStream.Size < 3641144)
		{
			set len = 32000
			Do inpStream.Rewind()
			while (len = 32000)
			{
				set len = 32000
				set xmlStr = xmlStr _ inpStream.Read(.len, .st)
			}

			$$$TRACE( "Stream Read to String" _ st _", length: " _ $L(xmlStr) _", " _ len)
			&SQL(INSERT INTO IHC_ERP.XMLData
				(ProcessDtTm,  FileName, xmlData, SenderID, ReceiverID, Gtin, PurchaseOrder, TransactionType, SessionID, SequenceID)
				values 
				(:procDtTm, :flNm, :xmlStr, :sender, :receiver, :gtin, :purchaseOrder, :tran, :sessionID, :sequenceID  ))
			IF SQLCODE<0 
			{
				$$$LOGERROR( "SQLCODE error " _ SQLCODE _ " " _ %msg)  
				if (SQLCODE = -119)
				{
					$$$TRACE( " - Duplicate Row")
				}
				else
				{
					set stat = $$$ERROR($$$SQLError,  procDtTm_", "_receiver_", "_sender_", "_flNm)
					QUIT
				}
			}
			else
			{
				$$$TRACE("INSERT INTO IHC_ERP.XMLData. SQLCODE: " _ SQLCODE _ ", Count: " _ %ROWCOUNT _ "; ROWID: " _ %ROWID)
			}
		}
		else // XML stream
		{
			set xmlStr = ""
			&SQL(INSERT INTO IHC_ERP.XMLData
				(ProcessDtTm,  FileName, xmlData, SenderID, ReceiverID, Gtin, PurchaseOrder, TransactionType, SessionID, SequenceID)
				values 
				(:procDtTm, :flNm, :xmlStr, :sender, :receiver, :gtin, :purchaseOrder, :tran, :sessionID, :sequenceID ))
			IF SQLCODE<0 
			{
				$$$LOGERROR( "SQLCODE error " _ SQLCODE _ " " _ %msg)  
				if (SQLCODE = -119)
				{
					$$$TRACE( " - Duplicate Row")
				}
				else
				{
					set stat = $$$ERROR($$$SQLError,  procDtTm_", "_receiver_", "_sender_", "_flNm)
					QUIT
				}
			}
			else
			{
				set rowId = %ROWID
				$$$TRACE( "INSERT INTO IHC_ERP.XMLData Count: " _", " _ %ROWCOUNT _ "; ROWID: " _ rowId)
				set obj = ##class(IHC.ERP.XMLData).%OpenId(rowId)
				if ($ISOBJECT(obj))
				{
					set obj.xmlDataStream = inpStream
					set stat = obj.%Save()
					$$$TRACE( "Save stream with IHC_ERP.XMLData: " _ obj.%Id())
				}   
			}
		}
	} 

	return stat

set stat = $$$OK
if (sessionID = 0)
{
	set sessionID = $$$JobSessionId
}
if (procDtTm = "")
{
	set procDtTm = $ZDATETIME($HOROLOG,3, 1)
}
Do inpStream.Rewind()
$$$TRACE("In StoreErpText: " _ flNm _", " _ inpStream.Size)
set tran = "Other"

$$$TRACE( "Stream length: " _ inpStream.Size)
set dataStr = ""

set len = 32000
Do inpStream.Rewind()
while (len = 32000)
{
	set len = 32000
	set dataStr = dataStr _ inpStream.Read(.len, .st)
}

&SQL(INSERT INTO IHC_ERP.TextData
	(ProcessDtTm,  FileName, textData, SenderID, ReceiverID, TransactionType, SessionID, SequenceID)
	values 
	(:procDtTm, :flNm, :dataStr, '-', '-', :tran, :sessionID, :sequenceID  ))
$$$TRACE( "Insert: " _ tran _": " _ SQLCODE)
IF SQLCODE<0
{
	set stat = $$$ERROR($$$SQLError, "INSERT INTO IHC_ERP.TextData failed: " _ SQLCODE)
}

 return stat

set stat = $$$OK
set dataStr = ""
set sendingApplication = ""
set sendingFacility = ""
set receivingApplication = ""
set receivingFacility = ""
set messageType = ""
set messageControlId = ""
set triggerName = ""
set caseNumber = "" 
set itemNumber = ""
set medicalRecordNumber = ""
set patientAccount = ""
set purchaseOrder = ""

if ( ($IsObject(inpStream)) && (inpStream.Size > 0) )
{
	if (sessionID = 0)
	{
		set sessionID = $$$JobSessionId
	}
	if (procDtTm = "")
	{
		set procDtTm = $ZDATETIME($HOROLOG,3, 1)
	}
	Do inpStream.Rewind()
	$$$TRACE("In StoreErpHL7Data: " _ flNm _", " _ inpStream.Size)
	set hl7Msg = ##class(EnsLib.HL7.Message).ImportFromLibraryStream(inpStream, .sc)
	if ( ($$$ISOK(sc)) && ($IsObject(hl7Msg)) && (hl7Msg.%Extends("EnsLib.HL7.Message")) )
	{
		$$$TRACE("Name:" _ hl7Msg.Name _ " Version:" _ hl7Msg.TypeVersion)
		set hl7Msg.DocType = hl7Msg.TypeVersion _ ":" _ hl7Msg.Name
		$$$TRACE("DocName:" _ hl7Msg.DocType)
		set dataStr = hl7Msg.OutputToString()

		If hl7Msg.GetValueAt("MSH:3.2") '= ""
		{
			set sendingApplication = hl7Msg.GetValueAt("MSH:3.1") _ "_" _ hl7Msg.GetValueAt("MSH:3.2")
		}
		else
		{
			set sendingApplication = hl7Msg.GetValueAt("MSH:3.1")
		}

		If hl7Msg.GetValueAt("MSH:4.2") '= ""
		{
			set sendingFacility = hl7Msg.GetValueAt("MSH:4.1") _ "_" _ hl7Msg.GetValueAt("MSH:4.2")
		}
		else
		{
			set sendingFacility = hl7Msg.GetValueAt("MSH:4.1")
		}

		If hl7Msg.GetValueAt("MSH:5.2") '= ""
		{
			set receivingApplication = hl7Msg.GetValueAt("MSH:5.1") _ "_" _ hl7Msg.GetValueAt("MSH:5.2")
		}
		else
		{
			set receivingApplication = hl7Msg.GetValueAt("MSH:5.1")
		}

		If hl7Msg.GetValueAt("MSH:6.2") '= ""
		{
			set receivingFacility = hl7Msg.GetValueAt("MSH:6.1") _ "_" _ hl7Msg.GetValueAt("MSH:6.2")
		}
		else
		{
			set receivingFacility = hl7Msg.GetValueAt("MSH:6.1")
		}

		set messageType = "ERP-" _ hl7Msg.DocType
		set messageControlId = hl7Msg.GetValueAt("MSH:10")

		If (hl7Msg.DocType [ "2.6:MFN_M16")
		{
			set itemNumber = hl7Msg.GetValueAt("MFEgrp(1).ITM:1.1")
		}
		elseif (hl7Msg.DocType [ "2.6:OMS_O05")
		{
			set triggerName = hl7Msg.GetValueAt("PIDgrp(1).ZCS:3")
			set caseNumber = hl7Msg.GetValueAt("PIDgrp(1).ORC:2.1")
			set medicalRecordNumber = hl7Msg.GetValueAt("PIDgrp(1).PID:3.1")
			set patientAccount = hl7Msg.GetValueAt("PIDgrp(1).PID:18")
		}
		elseif ((hl7Msg.DocType [ "2.6:SIU_S12") || (hl7Msg.DocType [ "2.6:SIU_S13") || (hl7Msg.DocType [ "2.6:SIU_S14") || (hl7Msg.DocType [ "2.6:SIU_S15"))
		{
			set triggerName = hl7Msg.GetValueAt("ZCS:3")
			set caseNumber = hl7Msg.GetValueAt("SCH:2.1")
			set medicalRecordNumber = hl7Msg.GetValueAt("PIDgrp(1).PID:3.1")
			set patientAccount = hl7Msg.GetValueAt("PIDgrp(1).PID:18")
		}
		elseif (hl7Msg.DocType [ "2.6:ZTS_TS1")
		{
			set purchaseOrder = hl7Msg.GetValueAt("ZSHgrp(1).ZPOgrp(1).ZPO:3")
		}

		&SQL(INSERT INTO IHC_ERP.HL7Data
			(ProcessDtTm,  hl7Data, SendingApplication, SendingFacility, ReceivingApplication, ReceivingFacility, 
			MessageType, MessageControlId, SessionID, SequenceID,
			TriggerName, CaseNumber, ItemNumber, MedicalRecordNumber, PatientAccount, PurchaseOrder)
			values 
			(:procDtTm, :dataStr, :sendingApplication, :sendingFacility, :receivingApplication, :receivingFacility,
			:messageType, :messageControlId, :sessionID, :sequenceID,
			:triggerName, :caseNumber, :itemNumber, :medicalRecordNumber, :patientAccount, :purchaseOrder))
		$$$TRACE( "Insert: " _ "hl7" _": " _ SQLCODE)
		IF SQLCODE<0
		{
			set stat = $$$ERROR($$$SQLError, "INSERT INTO IHC_ERP.HL7Data failed: " _ SQLCODE)
		}

	} //hl7
}
else
{
	set stat = $$$ERROR($$$GeneralError, "Invalid stream object: " _ inpStream)
}
return stat

set ctrlNum = 1
set ctlNm = $ZSTRIP(ConfigName, "<>W")_","_$ZSTRIP(sender, "<>W")_","_$ZSTRIP(receiver, "<>W")_","_$ZSTRIP(transType, "<>W")

if ($DATA(^[$NAMESPACE]HL7ControlNumber(ctlNm)) '= 0)
{
	SET ctrlNum = $INCREMENT(^[$NAMESPACE]HL7ControlNumber(ctlNm))
}
set ^[$NAMESPACE]HL7ControlNumber(ctlNm) = ctrlNum
return ctrlNum

	$$$TRACE("SplitXML for " _ docTypeName _ ", " _  splitName)
	set count = 0
	set status = ##class(%XML.TextReader).ParseFile(flNm,.textreader)
	if $$$ISERR(status) {do $System.Status.DisplayError(status) quit}
	Set tStream = ##class(%Library.FileCharacterStream).%New()
	set mylist=##class(%ListOfDataTypes).%New()

	while textreader.Read()
	{
		If (textreader.NodeType = "element") && (textreader.Name = splitName) 
		{		
			if (count > 0)
			{
				Do tStream.Rewind()
				Do mylist.Insert(tStream)
			}
			set count = count + 1
			Set tStream = ##class(%Library.FileCharacterStream).%New()
			Do tStream.Write( "<" _ docTypeName _ nmSpace _ ">")
		}

 	     If textreader.NodeType = "startprefixmapping"
		{
			set name1 = textreader.Name
		}		
		elseif textreader.NodeType = "element"
		{
			Do tStream.Write( "<" _ textreader.Name _ ">")
		}
		elseif textreader.NodeType = "chars"
		{
			Do tStream.Write( $zconvert(textreader.Value, "o", "XML") )
		}
		elseif (textreader.NodeType = "endelement") && (textreader.Name '= docTypeName) 
		{
			Do tStream.Write( "</" _ textreader.Name _ ">")
		}

		If (textreader.NodeType = "endelement") && (textreader.Name = splitName)
		{
			Do tStream.Write("</" _ docTypeName _ ">")
		}

	}

	// Last record
	Do tStream.Rewind()
	Do mylist.Insert(tStream)   

	$$$TRACE("SplitXML Count:" _ mylist.Count())  
	return mylist
